arguments.new_string:
# Parse invoice data from text
# Format: From: Vendor X, Total $XXXX.XX, Payment IBAN: X, PO Number: X
invoice_data = {
    'page': page_num + 1,
    'vendor_name': None,
    'amount': None,
    'iban': None,
    'po_number': None
}

# Extract vendor name
lines = text.split('\n')
for line in lines:
    if line.startswith('From:'):
        invoice_data['vendor_name'] = line.split(':', 1)[1].strip()
    elif 'Total $' in line:
        try:
            import re
            match = re.search(r'Total \$([\d,]+\.?\d*)', line)
            if match:
                amount_str = match.group(1).replace(',', '')
                invoice_data['amount'] = float(amount_str)
        except:
            pass
    elif 'Payment IBAN:' in line:
        invoice_data['iban'] = line.split(':', 1)[1].strip()
    elif 'PO Number:' in line:
        invoice_data['po_number'] = line.split(':', 1)[1].strip()

